import sys

values = list(map(int, sys.stdin.read().split()))
length = values[0]
edges = {divmod(edge, 10) for edge in values[1:]}
labels = sorted({v for edge in edges for v in edge})
index = {v: i for i, v in enumerate(labels)}
adj = [[] for _ in labels]
for u, v in edges:
    adj[index[u]].append(index[v])
# Each state stores (number of paths, sum of their decimal encodings).
states = {(1 << i, i): (1, v) for i, v in enumerate(labels)}
if length >= len(labels):
    print(0)
else:
    for _ in range(length):
        following = {}
        for (mask, last), (count, total) in states.items():
            for nxt in adj[last]:
                if mask & (1 << nxt):
                    continue
                key = (mask | (1 << nxt), nxt)
                old_count, old_sum = following.get(key, (0, 0))
                following[key] = (old_count + count,
                                  old_sum + 10 * total + labels[nxt] * count)
        states = following
    print(sum(total for count, total in states.values()))
